<template>
  <div class="pl-body">
    <!-- 搜索框 -->
    <div class="pl-search">
      <input v-model.trim="keyword" placeholder="搜索部件 / 子部件…" />
      <span v-if="keyword" class="pl-clear" @click="keyword = ''">×</span>
    </div>

    <!-- 六大分组 -->
    <section v-for="sec in sections" :key="sec.id" class="pl-sec">
      <div class="pl-sec-head">
        <i :style="{ background: sec.color }"></i>
        <b>{{ sec.name }}</b>
        <!-- combo-list 用 items.length：运行时新增的窗（W9/W10 由 applyWallWindows 追加）也要计入，
             静态 count 只在 catalog 构建时算过一次（2026-09-14 修） -->
        <em>{{ sec.type === 'combo-list' ? sec.items.length : sec.count }} {{ sec.unit }}</em>
      </div>

      <!-- 组合体列表：窗户 / 门 / 屋顶 / 地板 -->
      <template v-if="sec.type === 'combo-list'">
        <div style="display: flex;gap:6px;flex-wrap: wrap">
          <div v-for="item in visibleItems(sec)" :key="item.id" class="pl-combo"
            :class="{ on: isComboActive(sec, item) }" @click="onComboClick(sec, item)"
            @dblclick="onComboDblClick(sec, item)">
            <div class="pl-combo-row">
              <span class="pl-combo-name">{{ item.name }}</span>
            </div>
          </div>
        </div>
      </template>

      <!-- 平铺分组：墙体 / 框架 -->
      <template v-else>
        <div v-for="grp in visibleGroups(sec)" :key="grp.id" class="pl-flat-group">
          <div class="pl-flat-title">{{ grp.name }}（{{ grp.count }} 件）</div>
          <div style="display: flex;gap:6px;flex-wrap: wrap;padding: 8px;border: 1px solid #e8edf3;border-top: 0;">
            <div v-for="p in grp.parts" :key="grp.id + '-' + p.name" class="pl-part"
              :class="{ sel: isPartActive(sec, p) }" @click="onPartClick(sec, grp, p)"
              @dblclick="onPartDblClick(sec, grp, p)">
              <span class="pl-dot"></span>
              <span class="pl-pname">{{ p.name }}</span>
            </div>
          </div>
        </div>
      </template>
    </section>

    <div v-if="isEmpty" class="pl-empty">未找到匹配的部件</div>
  </div>
</template>

<script>
import { ref, computed, reactive } from 'vue'
import { editorState, selectItem, selectPart, requestFocus } from '../../lib/editorState'

const MAT_SHORT = {
  'M_0014_DarkSalmon': 'Salmon',
  'M_0135_DarkGray': 'DarkGray',
  'M_0010_Snow': 'Snow',
  'Translucent_Glass_Gray': 'Glass'
}

export default {
  name: 'PanelLibrary',
  props: {
    sections: { type: Array, required: true }
  },
  setup(props) {
    const keyword = ref('')
    const expanded = reactive({})
    let clickTimer = null

    const getSections = () => props.sections

    const hasAnyVisible = computed(() => {
      if (!keyword.value) return true
      return getSections().some((s) => visibleCount(s) > 0)
    })

    const isEmpty = computed(() => {
      return !!keyword.value && !hasAnyVisible.value
    })

    function matches(item, q) {
      const text = (item.name + ' ' + item.group + ' ' + (item.role || '') + ' ' + item.parts.map((p) => p.name + ' ' + p.mesh).join(' ')).toLowerCase()
      return text.includes(q)
    }
    function visibleCount(sec) {
      const q = keyword.value.toLowerCase()
      if (!q) return sec.type === 'combo-list' ? sec.items.length : sec.groups.reduce((n, g) => n + g.parts.length, 0)
      if (sec.type === 'combo-list') return sec.items.filter((it) => matches(it, q)).length
      return sec.groups.reduce((n, g) => n + g.parts.filter((p) => (p.name + ' ' + p.mesh + ' ' + p.sub).toLowerCase().includes(q)).length, 0)
    }
    function visibleItems(sec) {
      const q = keyword.value.toLowerCase()
      if (!q) return sec.items
      return sec.items.filter((it) => matches(it, q))
    }
    function visibleGroups(sec) {
      const q = keyword.value.toLowerCase()
      if (!q) return sec.groups
      return sec.groups
        .map((g) => ({ ...g, parts: g.parts.filter((p) => (p.name + ' ' + p.mesh + ' ' + p.sub).toLowerCase().includes(q)) }))
        .filter((g) => g.parts.length)
    }

    const isComboActive = (sec, item) => {
      const s = editorState.selected
      return !!(s && s.kind === 'combo' && s.section.id === sec.id && s.item.id === item.id)
    }
    const isPartActive = (sec, p) => {
      const s = editorState.selected
      return !!(s && s.kind === 'part' && s.section.id === sec.id && s.part.id === p.id)
    }

    /* ---- 单击：选中 + 视角聚焦（不切面板）；双击：选中 + 视角聚焦 + 切属性面板 ----
       单击延迟 220ms 执行，以便识别双击。 */
    function scheduleSingle(fn) {
      clearTimeout(clickTimer)
      clickTimer = setTimeout(fn, 220)
    }

    function onComboClick(sec, item) {
      expanded[item.id] = !expanded[item.id]
      scheduleSingle(() => {
        selectItem(sec, item, false)
        requestFocus(item.id)
      })
    }
    function onComboDblClick(sec, item) {
      clearTimeout(clickTimer)
      expanded[item.id] = true
      selectItem(sec, item, true)
      requestFocus(item.id)
    }
    function onPartClick(sec, grp, p) {
      scheduleSingle(() => {
        selectPart(sec, grp, p, false)
        requestFocus(p.id)
      })
    }
    function onPartDblClick(sec, grp, p) {
      clearTimeout(clickTimer)
      selectPart(sec, grp, p, true)
      requestFocus(p.id)
    }

    const sizeText = (s) => s.map((v) => +v.toFixed(2)).join(' × ')
    const shortMat = (m) => {
      if (!m) return ''
      const parts = m.split('+').map((x) => MAT_SHORT[x] || x.replace(/^M_\d+_/, ''))
      return parts.join('+')
    }

    return {
      keyword, expanded, isEmpty, visibleItems, visibleGroups,
      isComboActive, isPartActive, onComboClick, onComboDblClick,
      onPartClick, onPartDblClick,
      sizeText, shortMat
    }
  }
}
</script>

